node -e '
import { spawn } from "node:child_process";

const srv = spawn("npx", ["next", "dev", "--port", "4010"], { stdio: ["ignore", "pipe", "pipe"] });
let output = "";
srv.stdout.on("data", (d) => { output += d.toString(); });
srv.stderr.on("data", (d) => { output += d.toString(); });

setTimeout(async () => {
  try {
    const res1 = await fetch("http://localhost:4010/");
    await res1.text();
    const res2 = await fetch("http://localhost:4010/projects/acme");
    const html = await res2.text();
    await new Promise((r) => setTimeout(r, 2000));
    console.log("HTML includes title:", html.includes("Acme Storefront"));
    console.log("HTML includes description:", html.includes("Commerce storefront and checkout."));
    console.log("HTML includes activity:", html.includes("Production deployment"));
    console.log("Server output:\n" + output);
  } finally {
    srv.kill();
    process.exit(0);
  }
}, 5000);
'

