import { spawn } from "node:child_process";

const srv = spawn("npx", ["next", "start", "--port", "4011"], { stdio: ["ignore", "pipe", "pipe"] });
setTimeout(async () => {
  try {
    const start = Date.now();
    const res = await fetch("http://localhost:4011/projects/acme", {
      headers: {
        "RSC": "1",
        "Next-Router-Prefetch": "2",
        "Next-Router-State-Tree": encodeURIComponent(JSON.stringify(["", {"children": ["projects", {"children": [["slug", "acme", "d"], {"children": ["__PAGE__", {}]}]}]}, null, null, true])),
      }
    });
    const text = await res.text();
    const elapsed = Date.now() - start;
    console.log("Prefetch status:", res.status, "elapsed:", elapsed + "ms");
    console.log("Prefetch includes title:", text.includes("Acme Storefront"));
    console.log("Prefetch includes fallback:", text.includes("Loading details..."));
    console.log("Prefetch includes description:", text.includes("Commerce storefront and checkout."));
    console.log("Prefetch includes activity:", text.includes("Production deployment"));
  } finally {
    srv.kill();
    process.exit(0);
  }
}, 2000);
'

